# Resend (https://resend.com) — transactional email
RESEND_API_KEY=re_placeholder
# Must be on a domain verified in Resend (or onboarding@resend.dev while testing)
RESEND_FROM_EMAIL=Notely <hello@example.com>
# Public base URL used to build links in emails
APP_URL=http://localhost:3000
EOF
mkdir -p src/lib
cat > src/lib/email.ts <<'EOF'
import { Resend } from "resend";

let client: Resend | undefined;

function getClient(): Resend | undefined {
  const key = process.env.RESEND_API_KEY;
  if (!key) return undefined;
  client ??= new Resend(key);
  return client;
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

type Message = { to: string; subject: string; html: string; text: string };

// Never throws: Resend resolves to { error } on refusal, and a failed email
// must not break the request that triggered it.
async function send(message: Message): Promise<boolean> {
  const resend = getClient();
  const from = process.env.RESEND_FROM_EMAIL;
  if (!resend || !from) {
    console.warn(`[email] RESEND_API_KEY/RESEND_FROM_EMAIL not set; skipping "${message.subject}"`);
    return false;
  }
  try {
    const { error } = await resend.emails.send({ from, ...message });
    if (error) {
      console.error(`[email] send failed: ${error.name}: ${error.message}`);
      return false;
    }
    return true;
  } catch (err) {
    console.error("[email] send threw", err);
    return false;
  }
}

export function appUrl(): string {
  return (process.env.APP_URL ?? "http://localhost:3000").replace(/\/$/, "");
}

export function sendWelcomeEmail(user: { email: string; name: string }) {
  const url = `${appUrl()}/dashboard`;
  const name = escapeHtml(user.name);
  return send({
    to: user.email,
    subject: "Welcome to Notely",
    html: `<p>Hi ${name},</p><p>Welcome to Notely! Your account is ready.</p><p><a href="${url}">Open your dashboard</a></p>`,
    text: `Hi ${user.name},\n\nWelcome to Notely! Your account is ready.\n\nOpen your dashboard: ${url}`,
  });
}

export function sendPasswordResetEmail(user: { email: string; name: string }, resetUrl: string) {
  const name = escapeHtml(user.name);
  return send({
    to: user.email,
    subject: "Reset your Notely password",
    html: `<p>Hi ${name},</p><p>We received a request to reset your password. This link expires in 1 hour:</p><p><a href="${escapeHtml(resetUrl)}">Reset password</a></p><p>If you didn't ask for this, you can ignore this email.</p>`,
    text: `Hi ${user.name},\n\nWe received a request to reset your password. This link expires in 1 hour:\n${resetUrl}\n\nIf you didn't ask for this, you can ignore this email.`,
  });
}
EOF
cat >> src/lib/users.ts <<'EOF'

export async function createUser(input: { email: string; name: string }): Promise<User> {
  const email = input.email.trim().toLowerCase();
  if (users.some((u) => u.email === email)) {
    throw new Error("A user with this email already exists");
  }
  const user: User = {
    id: String(users.length + 1),
    email,
    name: input.name.trim(),
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  await sendWelcomeEmail(user);
  return user;
}

const RESET_TTL_MS = 60 * 60 * 1000;
// Token hashes only, so a leaked store doesn't leak usable links.
const resetTokens = new Map<string, { userId: string; expiresAt: number }>();

const hashToken = (token: string) => createHash("sha256").update(token).digest("hex");

// Silent for unknown emails so callers can't use it to discover accounts.
export async function requestPasswordReset(email: string): Promise<void> {
  const user = users.find((u) => u.email === email.trim().toLowerCase());
  if (!user) return;
  const token = randomBytes(32).toString("base64url");
  resetTokens.set(hashToken(token), { userId: user.id, expiresAt: Date.now() + RESET_TTL_MS });
  await sendPasswordResetEmail(user, `${appUrl()}/reset-password?token=${token}`);
}

// Validates and consumes a reset token; returns the user it belongs to.
// Setting the new password is left to the auth layer, which doesn't exist yet.
export async function consumePasswordResetToken(token: string): Promise<User | undefined> {
  const key = hashToken(token);
  const entry = resetTokens.get(key);
  resetTokens.delete(key);
  if (!entry || entry.expiresAt < Date.now()) return undefined;
  return getUser(entry.userId);
}
EOF
